package handler

import (
	"context"
	"net/http"
)

// Handler is the interface that all feature handlers must implement.
// This allows for consistent route registration and lifecycle management.
type Handler interface {
	// Name returns the unique name of this handler/module.
	Name() string

	// RegisterRoutes registers all HTTP routes for this handler on the given ServeMux.
	// The context is derived from the server's root context and can be used for
	// cancellation/timeouts during startup.
	RegisterRoutes(mux *http.ServeMux, ctx context.Context)
}

// Closer is an optional interface for handlers that need cleanup on shutdown.
type Closer interface {
	Close() error
}

package environ

import (
	"context"
	"fmt"
	"net/http"
	"os"
	"runtime"
	"strconv"
	"strings"
	"sync/atomic"
	"time"

	"github.com/prometheus/client_golang/prometheus"
	"github.com/vasu1124/introspect/pkg/assets"
	"github.com/vasu1124/introspect/pkg/handler"
	"github.com/vasu1124/introspect/pkg/logger"
	"github.com/vasu1124/introspect/pkg/network"
	"github.com/vasu1124/introspect/pkg/osinfo"
	"github.com/vasu1124/introspect/pkg/version"
)

var count uint32

var (
	requestCount = prometheus.NewCounterVec(
		prometheus.CounterOpts{
			Name: "environ_requests_total",
			Help: "Total number of requests to environ endpoint",
		},
		[]string{"proto"},
	)
	requestDuration = prometheus.NewHistogramVec(
		prometheus.HistogramOpts{
			Name:    "environ_request_duration_seconds",
			Help:    "Duration of environ requests in seconds",
			Buckets: prometheus.DefBuckets,
		},
		[]string{"proto"},
	)
)

func init() {
	prometheus.MustRegister(requestCount)
	prometheus.MustRegister(requestDuration)
}

// Handler implements server.Handler for the environ endpoint.
type Handler struct{}

// New creates a new environ handler.
func New() *Handler {
	return &Handler{}
}

// Name implements server.Handler.
func (h *Handler) Name() string {
	return "environ"
}

// RegisterRoutes implements server.Handler.
func (h *Handler) RegisterRoutes(mux *http.ServeMux, ctx context.Context) {
	mux.HandleFunc("/environ", h.ServeHTTP)
	logger.Log.Info("[environ] registered /environ")
}

// ServeHTTP handles the environ request.
func (h *Handler) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	atomic.AddUint32(&count, 1)

	start := time.Now()
	h.serveEnviron(w, r)
	duration := time.Since(start).Seconds()

	proto := strconv.Itoa(r.ProtoMajor) + "." + strconv.Itoa(r.ProtoMinor)
	requestCount.WithLabelValues(proto).Inc()
	requestDuration.WithLabelValues(proto).Observe(duration)
}

func (h *Handler) serveEnviron(w http.ResponseWriter, r *http.Request) {
	err := r.ParseForm()
	if err != nil {
		logger.Log.Error(err, "[environ] ParseForm error")
	}

	envMap := make(map[string]string)
	for _, env := range os.Environ() {
		kv := strings.SplitN(env, "=", 2)
		if len(kv) == 2 {
			envMap[kv[0]] = kv[1]
		}
	}

	requestMap := map[string][]string{
		"ContentLength":  {strconv.FormatInt(r.ContentLength, 10)},
		"Host":           {r.Host},
		"RemoteAddr":     {r.RemoteAddr},
		"Proto":          {r.Proto},
		"Method":         {r.Method},
		"Referer":        {r.Referer()},
		"RequestURI":     {r.RequestURI},
		"TransferEncoding": r.TransferEncoding,
	}

	processMap := map[string]string{
		"GO ARCH":           runtime.GOARCH,
		"GO OS":             runtime.GOOS,
		"GO Version":        runtime.Version(),
		"GO NumCPU":         strconv.Itoa(runtime.NumCPU()),
		"GO NumGoroutine":   strconv.Itoa(runtime.NumGoroutine()),
		"Introspect Version": version.Get().GitVersion,
		"Introspect TreeState": version.Get().GitTreeState,
		"Introspect Commit": version.Get().GitCommit,
		"Introspect BuildDate": version.Get().BuildDate,
	}

	serverMap := map[string]string{
		"Machine Architecture": osinfo.Utsname.Machine,
		"Nodename":             osinfo.Utsname.Nodename,
	}

	data := struct {
		assets.CommonData
		Environment map[string]string
		Header      map[string][]string
		Form        map[string][]string
		Request     map[string][]string
		Process     map[string]string
		OS          map[string]string
		Server      map[string]string
		Counter     uint32
		Network     network.Data
	}{
		CommonData: assets.CommonData{Version: version.Version, Flag: version.Flag},
		Environment: envMap,
		Header:      r.Header,
		Form:        r.Form,
		Request:     requestMap,
		Process:     processMap,
		OS:          osinfo.OSrelease,
		Server:      serverMap,
		Counter:     count,
		Network:     network.NetworkData,
	}

	if err := assets.ExecuteTemplate(w, "environ.html", data); err != nil {
		logger.Log.Error(err, "[environ] executing template")
		fmt.Fprint(w, "[environ] executing template: ", err)
	}
}

// Ensure Handler implements handler.Handler.
var _ handler.Handler = (*Handler)(nil)

package assets

import (
	"embed"
	"html/template"
	"io/fs"
	"net/http"
	"strings"
)

//go:embed tmpl/*
var templateFS embed.FS

//go:embed css/*
var cssFS embed.FS

// CommonData contains data shared across all templates.
type CommonData struct {
	Version string
	Flag    bool
}

// Common returns the common template data (version and flag).
func Common() CommonData {
	return CommonData{Version: "0.0.0-dev", Flag: false}
}

// InitTemplates is kept for compatibility but does nothing.
// Templates are parsed per-request with layout + page.
func InitTemplates() error {
	return nil
}

// CSSHandler serves embedded CSS files.
func CSSHandler() http.Handler {
	// The embedded FS has files at css/switch.css, etc.
	// We need to serve them at /css/switch.css
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		// Remove /css/ prefix from path
		path := strings.TrimPrefix(r.URL.Path, "/css/")
		if path == "" {
			http.NotFound(w, r)
			return
		}

		// Look up file in embedded FS at css/{path}
		fullPath := "css/" + path
		data, err := fs.ReadFile(cssFS, fullPath)
		if err != nil {
			http.NotFound(w, r)
			return
		}

		// Set content type based on extension
		if strings.HasSuffix(path, ".css") {
			w.Header().Set("Content-Type", "text/css")
		} else if strings.HasSuffix(path, ".js") {
			w.Header().Set("Content-Type", "application/javascript")
		}
		w.Write(data)
	})
}

// FaviconHandler serves the embedded favicon.
func FaviconHandler() http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		data, err := fs.ReadFile(templateFS, "tmpl/favicon.ico")
		if err != nil {
			http.NotFound(w, r)
			return
		}
		w.Header().Set("Content-Type", "image/x-icon")
		w.Write(data)
	}
}

// ExecuteTemplate executes a page template with the layout.
// It parses layout.html + the named page template together to avoid block conflicts.
func ExecuteTemplate(w http.ResponseWriter, pageName string, data any) error {
	// Read layout template
	layoutContent, err := fs.ReadFile(templateFS, "tmpl/layout.html")
	if err != nil {
		return err
	}

	// Read page template
	pageContent, err := fs.ReadFile(templateFS, "tmpl/"+pageName)
	if err != nil {
		return err
	}

	// Parse the layout first under its file name ("layout.html") so that
	// templates that invoke {{template "layout.html" .}} can resolve it.
	tmpl, err := template.New("layout.html").Parse(string(layoutContent))
	if err != nil {
		return err
	}

	_, err = tmpl.New(pageName).Parse(string(pageContent))
	if err != nil {
		return err
	}

	// Execute the page template (which includes layout via {{template "layout.html" .}})
	return tmpl.ExecuteTemplate(w, pageName, data)
}

